import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  alertActionClasses,
  alertClasses,
  alertContentClasses,
  alertCustomColorClasses,
  alertDescriptionClasses,
  alertIconClasses,
  alertTitleClasses,
  alertVariantClasses,
} from "./view";
import type { AlertVariant } from "./view";

export {
  alertActionClasses,
  alertClasses,
  alertContentClasses,
  alertCustomColorClasses,
  alertDescriptionClasses,
  alertIconClasses,
  alertTitleClasses,
  alertVariantClasses,
};
export type { AlertVariant };

export type AlertStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  variant?: AlertVariant | undefined;
  classes?: string | undefined;
  style?: AlertStyle | undefined;
}>;

export type IconViewConfig = Readonly<{
  children: readonly (Html | string)[];
  classes?: string | undefined;
  style?: AlertStyle | undefined;
}>;

export type TitleViewConfig = Readonly<{
  children: readonly (Html | string)[];
  classes?: string | undefined;
  style?: AlertStyle | undefined;
}>;

export type DescriptionViewConfig = Readonly<{
  children: readonly (Html | string)[];
  variant?: AlertVariant | undefined;
  classes?: string | undefined;
  style?: AlertStyle | undefined;
}>;

export type ContentViewConfig = Readonly<{
  children: readonly Html[];
  classes?: string | undefined;
  style?: AlertStyle | undefined;
}>;

export type ActionViewConfig = Readonly<{
  children: readonly Html[];
  classes?: string | undefined;
  style?: AlertStyle | undefined;
}>;

const cn = (...values: readonly (string | undefined)[]): string =>
  values
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  variant = "Default",
  classes,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "alert"),
      h.DataAttribute("variant", variant),
      h.Class(
        cn(alertClasses, alertVariantClasses(variant), classes)
      ),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const iconView = <ParentMessage>({
  children,
  classes,
  style,
}: IconViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.Attribute("aria-hidden", "true"),
      h.Class(cn(alertIconClasses, classes)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const contentView = <ParentMessage>({
  children,
  classes,
  style,
}: ContentViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Class(cn(alertContentClasses, classes)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const titleView = <ParentMessage>({
  children,
  classes,
  style,
}: TitleViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.h3(
    [h.Class(cn(alertTitleClasses, classes)), h.Style(style ?? {})],
    children
  );
};

export const descriptionView = <ParentMessage>({
  children,
  variant = "Default",
  classes,
  style,
}: DescriptionViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("variant", variant),
      h.Class(cn(alertDescriptionClasses, classes)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const actionView = <ParentMessage>({
  children,
  classes,
  style,
}: ActionViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Class(cn(alertActionClasses, classes)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const view = <ParentMessage>({
  title,
  description,
  icon,
  action,
  variant = "Default",
  classes,
}: Readonly<{
  title: string;
  description: string;
  icon?: string | undefined;
  action?: Html | undefined;
  variant?: AlertVariant | undefined;
  classes?: string | undefined;
}>): Html =>
  rootView<ParentMessage>({
    variant,
    classes,
    children: [
      iconView<ParentMessage>({ children: [icon ?? "i"] }),
      contentView<ParentMessage>({
        children: [
          titleView<ParentMessage>({ children: [title] }),
          descriptionView<ParentMessage>({ children: [description], variant }),
          ...(action === undefined
            ? []
            : [actionView<ParentMessage>({ children: [action] })]),
        ],
      }),
    ],
  });

export type AlertVariant = "Default" | "Destructive";

export const alertClasses =
  "relative grid w-full gap-1 rounded-lg border px-4 py-3 text-sm";

export const alertVariantClasses = (variant: AlertVariant): string => {
  if (variant === "Destructive") {
    return "border-red-200 bg-red-50 text-red-950";
  }

  return "border-gray-200 bg-white text-gray-950";
};

export const alertIconClasses =
  "absolute left-4 top-4 grid size-4 place-items-center text-xs font-semibold";

export const alertContentClasses = "grid gap-1 pl-7";

export const alertTitleClasses = "font-medium leading-none tracking-normal";

export const alertDescriptionClasses =
  "text-sm leading-5 text-gray-600 data-[variant=Destructive]:text-red-700";

export const alertActionClasses = "mt-2 flex justify-start";

export const alertCustomColorClasses =
  "border-amber-200 bg-amber-50 text-amber-950";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Alert from "./index";

describe("alert", () => {
  test("renders default alert anatomy and role", () => {
    const view = (): Html =>
      Alert.rootView<never>({
        children: [
          Alert.iconView<never>({ children: ["i"] }),
          Alert.contentView<never>({
            children: [
              Alert.titleView<never>({ children: ["Heads up!"] }),
              Alert.descriptionView<never>({
                children: ["You can add components using the cli."],
              }),
            ],
          }),
        ],
      });

    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("alert")).toExist(),
      Scene.expect(Scene.role("heading", { name: "Heads up!" })).toExist(),
      Scene.expect(
        Scene.text("You can add components using the cli.")
      ).toExist(),
      Scene.expect(Scene.text("i")).toExist(),
      Scene.expect(Scene.role("alert")).toHaveClass("border-gray-200")
    );
  });

  test("renders destructive variant and action slot", () => {
    const h = html<never>();

    const view = (): Html =>
      Alert.view<never>({
        title: "Error",
        description: "Your session has expired. Please log in again.",
        icon: "!",
        variant: "Destructive",
        action: h.button([h.Type("button")], ["Log in"]),
      });

    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("alert")).toHaveAttr(
        "data-variant",
        "Destructive"
      ),
      Scene.expect(Scene.role("alert")).toHaveClass("border-red-200"),
      Scene.expect(Scene.role("button", { name: "Log in" })).toExist()
    );
  });
});
